import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    result = []
    for ch in out:
        if ch == '-' and (not result or result[-1] == '-'):
            continue
        result.append(ch)
    return ''.join(result).strip('-')
